/**
 * Generates `src/lib/lesson-manifest.ts` from `content/lessons/*.mdx`.
 *
 * Why: lesson MDX components are code-split (one async chunk per lesson), so
 * the app can no longer `import.meta.glob(..., { eager: true })` the modules
 * just to read their metadata. This manifest gives every consumer (lesson
 * lists, roadmap, badges, sitemap, prerenderer) the metadata synchronously
 * while the components stay lazy.
 *
 * Runs automatically via `prebuild` / `predev` / `pretest`. The generated file
 * is gitignored — never edit it by hand.
 */
import { writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { repoRoot, loadLessonMetas } from './lesson-meta.mjs';

const metas = loadLessonMetas();

const output = `// AUTO-GENERATED by scripts/seo/generate-manifest.mjs — do not edit.
// Regenerated from content/lessons/*.mdx on prebuild/predev/pretest.
import type { LessonMeta } from './lessons';

export const lessonManifest: LessonMeta[] = ${JSON.stringify(metas, null, 2)};
`;

writeFileSync(join(repoRoot, 'src', 'lib', 'lesson-manifest.ts'), output);
console.log(`lesson-manifest.ts: ${metas.length} lessons`);
